await using var client = new ServiceBusClient(connectionString);
ServiceBusSender sender = client.CreateSender("orders");
ServiceBusTransactionContext tx = await client.CreateTransactionAsync();
try
{
    await sender.SendMessageAsync(new ServiceBusMessage(json), tx);
    await client.CommitTransactionAsync(tx);      // the send becomes visible only now
}
catch { await client.RollbackTransactionAsync(tx); throw; }

